const SHELL = new URL("index.html", self.registration.scope).href;
const inflight = new Map();
/** The tracks in the music cache (hrefs), listed at start: a Range request is answered at once. */
const cached = new Set();
let listed = false;
const keyHref = (k) => (typeof k === 'string' ? k : k.url);
caches
  .open(MUSIC)
  .then((c) => c.keys())
  .then((keys) => keys.forEach((k) => cached.add(keyHref(k))))
